begin;
with j as (select * from jsonb_to_recordset($law7d0022$[{"code_id":"APK_RF","article_number":"99","version_date":"2002-07-24","article_text":"1. Арбитражный суд по заявлению организации или гражданина вправе принять предварительные обеспечительные меры, направленные на обеспечение имущественных интересов заявителя до предъявления иска.\n\nЗаявление об обеспечении имущественных интересов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n11. Арбитражный суд вправе по заявлению Банка России, поданному в случае установления им отрицательного значения величины собственных средств (капитала) кредитной организации, страховой организации, негосударственного пенсионного фонда, принять предварительные обеспечительные меры, предусматривающие наложение ареста на денежные средства, ценные бумаги и недвижимое имущество лиц, контролирующих кредитную организацию, страховую организацию, негосударственный пенсионный фонд, до подачи заявления о привлечении указанных лиц к субсидиарной ответственности, ответственности в форме возмещения убытков в соответствии с Федеральным законом от 26 октября 2002 года № 127-ФЗ \"О несостоятельности (банкротстве)\". Арбитражный суд выносит определение об оставлении заявления Банка России о принятии предварительных обеспечительных мер без движения, если при рассмотрении вопроса о принятии данного заявления к производству установит, что оно не содержит сведений, позволяющих с минимально необходимой степенью достоверности сделать обоснованные предположения о том, что ответчик, указанный в заявлении, является или являлся контролирующим лицом. Рассмотрение судом дела об оспаривании включения лица в перечень контролирующих кредитную организацию лиц в соответствии со статьей 576 Федерального закона от 10 июля 2002 года № 86-ФЗ \"О Центральном банке Российской Федерации (Банке России)\", перечень контролирующих страховую организацию лиц или перечень контролирующих негосударственный пенсионный фонд лиц в соответствии со статьей 767-1 Федерального закона от 10 июля 2002 года № 86-ФЗ \"О Центральном банке Российской Федерации (Банке России)\" не препятствует принятию арбитражным судом заявления Банка России о принятии предварительных обеспечительных мер, рассмотрению данного заявления и принятию предварительных обеспечительных мер в соответствии с настоящей частью.\n\nРазмер предварительных обеспечительных мер, принимаемых арбитражным судом по заявлению Банка России в соответствии с настоящей частью, не может превышать величину денежных средств, необходимых для восполнения собственных средств (капитала) кредитной организации, страховой организации, негосударственного пенсионного фонда в целях приведения их к величине, необходимой и достаточной для выполнения указанными организациями требований федеральных законов и нормативных актов Банка России.\n\n(Дополнение частью - Федеральный закон от 24.02.2021 № 23-ФЗ)\n\n2. Предварительные обеспечительные меры принимаются арбитражным судом по правилам, предусмотренным настоящей главой, с особенностями, установленными настоящей статьей.\n\nВ случае непредставления указанного документа арбитражный суд вправе предложить заявителю предоставить встречное обеспечение в соответствии со статьей 94 настоящего Кодекса и оставляет заявление об обеспечении имущественных интересов без движения по правилам статьи 128 настоящего Кодекса до представления документа, подтверждающего произведенное встречное обеспечение.\n\nПри подаче Банком России заявления о принятии предварительных обеспечительных мер в соответствии с частью 11 настоящей статьи предоставления встречного обеспечения в соответствии со статьей 94 настоящего Кодекса не требуется. (Дополнение абзацем - Федеральный закон от 24.02.2021 № 23-ФЗ)\n\nВ случае, если по требованию, в связи с которым подано заявление об обеспечении имущественных интересов, в силу закона обязательно соблюдение претензионного или иного досудебного порядка урегулирования спора, в определении устанавливаются срок для направления претензии (требования) другой стороне, не превышающий пятнадцати дней со дня вынесения определения, и срок для подачи искового заявления по такому требованию, не превышающий пяти дней со дня истечения установленного законом или договором срока для принятия сторонами мер по досудебному урегулированию в соответствии с частью 5 статьи 4 настоящего Кодекса. Если указанный порядок не является обязательным, в определении устанавливается срок, не превышающий пятнадцати дней со дня вынесения определения, для подачи искового заявления по требованию, в связи с которым судом приняты меры по обеспечению имущественных интересов заявителя.\n\nПри подаче Банком России заявления о принятии предварительных обеспечительных мер в соответствии с частью 11 настоящей статьи в определении об обеспечении имущественных интересов устанавливается срок, не превышающий тридцати дней со дня вынесения определения, для подачи искового заявления по требованию, в связи с которым судом приняты меры по обеспечению имущественных интересов Банка России. (Дополнение абзацем - Федеральный закон от 24.02.2021 № 23-ФЗ)\n\n(Часть в редакции Федерального закона от 01.07.2017 № 147-ФЗ)\n\nОб отмене обеспечения имущественных интересов выносится определение.\n\nКопии определения направляются заявителю и иным заинтересованным лицам не позднее следующего дня после дня вынесения определения.\n\nЛицо, в отношении имущества которого были приняты предварительные обеспечительные меры в соответствии с частью 11 настоящей статьи, вправе требовать по своему выбору от Банка России возмещения убытков или выплаты компенсации в порядке, предусмотренном статьей 98 настоящего Кодекса, если Банком России в установленный судом срок не было подано исковое заявление по требованию, в связи с которым арбитражным судом были приняты меры по обеспечению имущественных интересов Банка России, или если вступившим в законную силу судебным актом арбитражного суда в иске было отказано. (Дополнение абзацем - Федеральный закон от 24.02.2021 № 23-ФЗ)","article_title":"Статья 99. Предварительные обеспечительные меры","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"31e045cf3384e7aa6090b6a5d438d3384d694e1d5178707655984ded1b0a11f2"},{"code_id":"BK_RF","article_number":"1","version_date":"1998-07-31","article_text":"1. К бюджетным правоотношениям относятся:\n\nотношения,  возникающие между субъектами бюджетных правоотношений в процессе формирования доходов и осуществления расходов бюджетов бюджетной системы Российской Федерации,  осуществления государственных (муниципальных)  заимствований,  регулирования государственного (муниципального)  долга; (В редакции федеральных законов от 26.04.2007 № 63-ФЗ,  от 02.08.2019 № 278-ФЗ)\n\nотношения,  возникающие между субъектами бюджетных правоотношений в процессе составления и рассмотрения проектов бюджетов бюджетной системы Российской Федерации,  утверждения и исполнения бюджетов бюджетной системы Российской Федерации,  контроля за их исполнением,  осуществления бюджетного учета,  составления,  рассмотрения и утверждения бюджетной отчетности. (В редакции Федерального закона от 26.04.2007 № 63-ФЗ)\n\n2. Настоящий Кодекс устанавливает правовой статус участников бюджетного процесса,  правовые основы казначейского сопровождения,  применения бюджетных мер принуждения за совершение бюджетных нарушений. (В редакции федеральных законов от 26.07.2019 № 199-ФЗ,  от 01.07.2021 № 244-ФЗ)","article_title":"Статья 1. Правоотношения,  регулируемые Бюджетным кодексом Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"33dc8ff9a180d26000babe6e25ef00221db4bfd1d86d1334b82a1d671b1f7beb"},{"code_id":"BK_RF","article_number":"10","version_date":"1998-07-31","article_text":"К бюджетам бюджетной системы Российской Федерации относятся:\n\nфедеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации;\n\nбюджеты субъектов Российской Федерации и бюджеты территориальных государственных внебюджетных фондов;\n\nместные бюджеты,  в том числе:\n\nбюджеты муниципальных районов,  бюджеты муниципальных округов,  бюджеты городских округов,  бюджеты городских округов с внутригородским делением,  бюджеты внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ,  от 29.11.2014 № 383-ФЗ,  от 01.10.2020 № 311-ФЗ)\n\nбюджеты городских и сельских поселений,  бюджеты внутригородских районов. (В редакции Федерального закона от 29.11.2014 № 383-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 10. Структура бюджетной системы Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"50494720d2362ba6d723ff09eb7145444152da6beb325f7d64175f0262c9e23f"},{"code_id":"BK_RF","article_number":"11","version_date":"1998-07-31","article_text":"Федеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации разрабатываются и утверждаются в форме федеральных законов,  бюджеты субъектов Российской Федерации и бюджеты территориальных государственных внебюджетных фондов разрабатываются и утверждаются в форме законов субъектов Российской Федерации,  местные бюджеты разрабатываются и утверждаются в форме муниципальных правовых актов представительных органов муниципальных образований.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 11. Правовая форма бюджетов","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"568a143c4a92f91048daaeec89ce8dade0b130ac7d6e6492a015397159a11df1"},{"code_id":"BK_RF","article_number":"12","version_date":"1998-07-31","article_text":"Финансовый год соответствует календарному году и длится с 1 января по 31 декабря.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 12. Финансовый год","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"1c789ef65f4a656d5e053804f16c3fab7d953f77736b84d55fb83e0ca9c3b4c9"},{"code_id":"BK_RF","article_number":"13","version_date":"1998-07-31","article_text":"Федеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации предназначены для исполнения расходных обязательств Российской Федерации.\n\nИспользование федеральными органами государственной власти иных форм образования и расходования денежных средств,  предназначенных для исполнения расходных обязательств Российской Федерации,  не допускается.\n\nФедеральный бюджет и свод консолидированных бюджетов субъектов Российской Федерации (без учета межбюджетных трансфертов между этими бюджетами)  образуют консолидированный бюджет Российской Федерации.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 13. Федеральный бюджет и бюджеты государственных внебюджетных фондов Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d22c29391587f6764649cb0c09669f4c440cfdfbce8ff5ced15e6d72eae1ed51"},{"code_id":"BK_RF","article_number":"14","version_date":"1998-07-31","article_text":"Каждый субъект Российской Федерации имеет собственный бюджет и бюджет территориального государственного внебюджетного фонда.\n\nБюджет субъекта Российской Федерации (региональный бюджет)  и бюджет территориального государственного внебюджетного фонда предназначены для исполнения расходных обязательств субъекта Российской Федерации.\n\nИспользование органами государственной власти субъектов Российской Федерации иных форм образования и расходования денежных средств для исполнения расходных обязательств субъектов Российской Федерации не допускается.\n\nВ бюджетах субъектов Российской Федерации в соответствии с бюджетной классификацией Российской Федерации раздельно предусматриваются средства,  направляемые на исполнение расходных обязательств субъектов Российской Федерации,  возникающих в связи с осуществлением органами государственной власти субъектов Российской Федерации полномочий по предметам ведения субъектов Российской Федерации и полномочий по предметам совместного ведения,  указанных в частях 1 и 5 статьи 44 Федерального закона от 21 декабря 2021 года № 414-ФЗ \"Об общих принципах организации публичной власти в субъектах Российской Федерации\",  и расходных обязательств субъектов Российской Федерации,  осуществляемых за счет субвенций из федерального бюджета. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nБюджет субъекта Российской Федерации и свод бюджетов муниципальных образований,  входящих в состав субъекта Российской Федерации (без учета межбюджетных трансфертов между этими бюджетами) ,  образуют консолидированный бюджет субъекта Российской Федерации.\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 14. Бюджет субъекта Российской Федерации и бюджет территориального государственного внебюджетного фонда","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d503066f4ae75d90dfc811e75e37301d9bf35b64fdc03c0a78d1bc1f8d042ef3"},{"code_id":"BK_RF","article_number":"15","version_date":"1998-07-31","article_text":"Каждое муниципальное образование имеет собственный бюджет.\n\nБюджет муниципального образования (местный бюджет)  предназначен для исполнения расходных обязательств муниципального образования.\n\nИспользование органами местного самоуправления иных форм образования и расходования денежных средств для исполнения расходных обязательств муниципальных образований не допускается.\n\nВ местных бюджетах в соответствии с бюджетной классификацией Российской Федерации раздельно предусматриваются средства,  направляемые на исполнение расходных обязательств муниципальных образований,  возникающих в связи с осуществлением органами местного самоуправления полномочий по вопросам местного значения,  и расходных обязательств муниципальных образований,  исполняемых за счет субвенций из других бюджетов бюджетной системы Российской Федерации для осуществления отдельных государственных полномочий.\n\nБюджет муниципального района (районный бюджет)  и свод бюджетов городских и сельских поселений,  входящих в состав муниципального района (без учета межбюджетных трансфертов между этими бюджетами) ,  образуют консолидированный бюджет муниципального района.\n\nВ качестве составной части бюджетов городских,  сельских поселений,  внутригородских районов,  муниципальных районов (в отношении населенных пунктов,  других территорий,  расположенных на межселенных территориях) ,  муниципальных округов,  городских округов,  внутригородских муниципальных образований городов федерального значения Москвы,  Санкт-Петербурга и Севастополя могут быть предусмотрены сметы доходов и расходов отдельных населенных пунктов,  других территорий,  не являющихся муниципальными образованиями. (В редакции Федерального закона от 01.10.2020 № 311-ФЗ)\n\nБюджет городского округа с внутригородским делением и свод бюджетов внутригородских районов,  входящих в состав городского округа с внутригородским делением (без учета межбюджетных трансфертов между этими бюджетами) ,  образуют консолидированный бюджет городского округа с внутригородским делением. (Дополнение частью - Федеральный закон от 29.11.2014 № 383-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 15. Местный бюджет","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"67929442ae2ee61570e1e77f58603a00e1a2fd979125ba703e4fc46550b5dded"},{"code_id":"BK_RF","article_number":"16","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 16.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"17","version_date":"1998-07-31","article_text":"(Статья утратила силу - Федеральный закон от 26.04.2007 № 63-ФЗ)","article_title":"Статья 17.","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"57686dec82b0e1bf928e4df12f997fdd6e0ba3669b596117919b146468014624"},{"code_id":"BK_RF","article_number":"18","version_date":"1998-07-31","article_text":"1. Бюджетная классификация Российской Федерации является группировкой доходов,  расходов и источников финансирования дефицитов бюджетов бюджетной системы Российской Федерации,  используемой для составления и исполнения бюджетов,  а также группировкой доходов,  расходов и источников финансирования дефицитов бюджетов и (или)  операций сектора государственного управления,  используемой для ведения бюджетного (бухгалтерского)  учета,  составления бюджетной (бухгалтерской)  и иной финансовой отчетности,  обеспечивающей сопоставимость показателей бюджетов бюджетной системы Российской Федерации. (В редакции Федерального закона от 22.10.2014 № 311-ФЗ)\n\n2. Определение принципов назначения,  структуры,  порядка формирования и применения кодов бюджетной классификации Российской Федерации,  а также присвоение кодов составным частям бюджетной классификации Российской Федерации,  которые в соответствии с настоящим Кодексом являются едиными для бюджетов бюджетной системы Российской Федерации,  осуществляются Министерством финансов Российской Федерации с учетом положений пунктов 3 и 4 настоящей статьи. (В редакции  федеральных законов от 07.05.2013 № 104-ФЗ,  от 04.08.2023 № 416-ФЗ)\n\n3. Утверждение или изменение нормативных правовых актов Министерства финансов Российской Федерации,  регулирующих вопросы,  указанные в пункте 2 настоящей статьи,  пункте 6,  абзацах третьем и четвертом пункта 9 статьи 20,  абзацах четвертом - шестом пункта 4,  пунктах 7 и 8 статьи 21,  абзацах втором и третьем пункта 5 статьи 23,  пунктах 3 - 5 статьи 231 настоящего Кодекса,  осуществляется исключительно в связи с составлением или принятием федеральных законов о федеральном бюджете или о внесении изменений в федеральный закон о федеральном бюджете,  но не более одного раза в связи с составлением и не более одного раза в связи с принятием такого федерального закона,  за исключением случаев,  установленных в абзаце втором пункта 6,  абзаце пятом пункта 9 статьи 20,  пункте 9 статьи 21 и абзаце четвертом пункта 5 статьи 23 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)  (В редакции  Федерального закона от 24.06.2025 № 158-ФЗ)\n\n4. Нормативные правовые акты Министерства финансов Российской Федерации,  регулирующие вопросы,  указанные в пункте 2 настоящей статьи,  пункте 6 и абзаце третьем пункта 9 статьи 20,  пунктах 7 и 8 статьи 21,  абзаце втором пункта 5 статьи 23,  пунктах 3 - 5 статьи 231 настоящего Кодекса,  включая изменения в них,  обратной силы не имеют и применяются к отношениям,  возникшим не ранее дня их вступления в силу,  за исключением случаев,  установленных пунктом 9 статьи 21 и абзацем четвертым пункта 5 статьи 23 настоящего Кодекса. (Дополнение пунктом - Федеральный закон от 04.08.2023 № 416-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 18. Бюджетная классификация Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bcf1cb086a0855625535868452798b9d13d91c3560c1d6951ebf9d66aa267306"},{"code_id":"BK_RF","article_number":"19","version_date":"1998-07-31","article_text":"Бюджетная классификация Российской Федерации включает:\n\nклассификацию доходов бюджетов;\n\nклассификацию расходов бюджетов;\n\nклассификацию источников финансирования дефицитов бюджетов;\n\nклассификацию операций публично-правовых образований (далее - классификация операций сектора государственного управления) .\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 19. Состав бюджетной классификации Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4cda38fdcdf6a4291ae9def7d33e8761e6a45941d159ec3385e1b5bbb22a3419"},{"code_id":"BK_RF","article_number":"2","version_date":"1998-07-31","article_text":"Бюджетное законодательство Российской Федерации состоит из настоящего Кодекса и принятых в соответствии с ним федеральных законов о федеральном бюджете,  федеральных законов о бюджетах государственных внебюджетных фондов Российской Федерации,  законов субъектов Российской Федерации о бюджетах субъектов Российской Федерации,  законов субъектов Российской Федерации о бюджетах территориальных государственных внебюджетных фондов,  муниципальных правовых актов представительных органов муниципальных образований о местных бюджетах (далее - закон (решение)  о бюджете) ,  иных федеральных законов,  законов субъектов Российской Федерации и муниципальных правовых актов представительных органов муниципальных образований,  регулирующих правоотношения,  указанные в статье 1 настоящего Кодекса.\n\nФедеральные законы,  законы субъектов Российской Федерации,  муниципальные правовые акты представительных органов муниципальных образований,  предусмотренные частью первой настоящей статьи,  не могут противоречить настоящему Кодексу.\n\nВнесение изменений в Бюджетный кодекс Российской Федерации,  а также приостановление,  отмена и признание утратившими силу положений Бюджетного кодекса Российской Федерации осуществляются отдельными федеральными законами и не могут быть включены в тексты федеральных законов,  изменяющих (приостанавливающих,  отменяющих,  признающих утратившими силу)  другие законодательные акты Российской Федерации или содержащих самостоятельный предмет правового регулирования. (Дополнение частью - Федеральный закон от 07.05.2013 № 104-ФЗ)\n\n(Статья в редакции Федерального закона от 26.04.2007 № 63-ФЗ)","article_title":"Статья 2. Структура бюджетного законодательства Российской Федерации","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ff9b76412fffd26b6534c1f5793eaa3c346ba8928eee1694573d7e7fed056498"}]$law7d0022$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
